"""Regular Expression Matching — DP over (pattern index, string index).

'x*' either matches zero characters (skip both pattern chars) or one more copy
of x (consume a character and stay on the same pattern position).

Time: O(n*m)   Space: O(n*m)
"""
from functools import lru_cache


class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        @lru_cache(maxsize=None)
        def solve(i: int, j: int) -> bool:
            if j == len(p):
                return i == len(s)
            first = i < len(s) and p[j] in (s[i], ".")
            if j + 1 < len(p) and p[j + 1] == "*":
                return solve(i, j + 2) or (first and solve(i + 1, j))
            return first and solve(i + 1, j + 1)

        return solve(0, 0)
